using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using NUnit.Framework;using Rootborn.Game.Common;using Rootborn.Game.Localization;using Rootborn.Game.Save;using Rootborn.Game.WorldState;using Rootborn.Game.Encyclopedia;using Rootborn.UI.WorldState;using Rootborn.UI.Encyclopedia;using UnityEngine;using UnityEngine.UI;
namespace Rootborn.Tests.EditMode.UI {public sealed class UtilityModalReadabilityTests {
private const string CatalogJson="{\"entries\": [{\"key\": \"test.world.title\", \"ko\": \"\uc791\uc5c5\uc2e4 \ud655\uc7a5\", \"en\": \"Studio expanded\"}, {\"key\": \"test.world.desc\", \"ko\": \"\uc0c8 \uc791\uc5c5 \uacf5\uac04\uc774 \uc0dd\uacbc\uc5b4\uc694.\", \"en\": \"More workspace is available.\"}, {\"key\": \"test.world.location\", \"ko\": \"\ub514\uc790\uc778 \uc791\uc5c5\uc2e4\", \"en\": \"Design studio\"}, {\"key\": \"test.world.next\", \"ko\": \"\uc2dc\uc124\uc5d0\uc11c \uc0c8 \uc5c5\ubb34\ub97c \ud655\uc778\ud558\uc138\uc694.\", \"en\": \"Check the new work at your facility.\"}, {\"key\": \"test.ency.category\", \"ko\": \"\uc7a5\uc18c\", \"en\": \"Locations\"}, {\"key\": \"test.ency.title\", \"ko\": \"\uc2dc\uacc4\ud0d1\uc758 \uae30\ub85d\", \"en\": \"Clocktower notes\"}, {\"key\": \"test.ency.description\", \"ko\": \"\ub9c8\uc744\uc5d0\uc11c \ubc1c\uacac\ud55c \uae30\ub85d\uc785\ub2c8\ub2e4.\", \"en\": \"Notes found around town.\"}, {\"key\": \"test.ency.hint\", \"ko\": \"\ub9c8\uc744\uc758 \ubc1c\uacac \uc9c0\uc810\uc744 \uc0b4\ud3b4\ubcf4\uc138\uc694.\", \"en\": \"Look for a discovery point in town.\"}, {\"key\": \"test.ency.detail\", \"ko\": \"\ubc1c\uacac\ud55c \ub2e8\uc11c\ub97c \ub2e4\uc2dc \uc77d\uc5b4\ubcfc \uc218 \uc788\uc5b4\uc694.\", \"en\": \"Review the clues you have found.\"}, {\"key\": \"ui.encyclopedia.new\", \"ko\": \"\uc0c8 \ud56d\ubaa9\", \"en\": \"NEW\"}, {\"key\": \"day-result.world-badge.New\", \"ko\": \"\uc0c8\ub85c\uc6b4 \ubcc0\ud654\", \"en\": \"New\"}, {\"key\": \"day-result.world-badge.Shared\", \"ko\": \"\uacf5\uc720\", \"en\": \"Shared\"}, {\"key\": \"day-result.world-scope.Shared\", \"ko\": \"\uacf5\uc720\", \"en\": \"Shared\"}]}";
GameObject canvas;GameDataRegistry registry,previous;GameTextCatalog catalog;string language;readonly List<UnityEngine.Object> definitions=new List<UnityEngine.Object>();
[SetUp]public void Setup(){GameDataRegistryProvider.TryGet(out previous);language=GameText.Language;GameText.Language="ko";registry=ScriptableObject.CreateInstance<GameDataRegistry>();catalog=ScriptableObject.CreateInstance<GameTextCatalog>();catalog.ConfigureJson(CatalogJson);typeof(GameDataRegistry).GetField("_textCatalog",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(registry,catalog);GameDataRegistryProvider.SetOverrideForTests(registry);SaveService.SetRootDirectoryForTests(Path.Combine(Path.GetTempPath(),"farmer-utility-modal-"+Guid.NewGuid().ToString("N")));canvas=new GameObject("ModalReadabilityCanvas",typeof(RectTransform),typeof(Canvas));((RectTransform)canvas.transform).sizeDelta=new Vector2(1920,1080);}
[TearDown]public void Cleanup(){if(canvas!=null)UnityEngine.Object.DestroyImmediate(canvas);foreach(var d in definitions)if(d!=null)UnityEngine.Object.DestroyImmediate(d);definitions.Clear();GameDataRegistryProvider.SetOverrideForTests(previous);GameText.Language=language;SaveService.SetRootDirectoryForTests(null);if(registry!=null)UnityEngine.Object.DestroyImmediate(registry);if(catalog!=null)UnityEngine.Object.DestroyImmediate(catalog);}
GameObject Child(string name){var g=new GameObject(name,typeof(RectTransform));g.transform.SetParent(canvas.transform,false);return g;}
WorldStateSummaryModel Model(int index=0)=>new WorldStateSummaryModel("world.fixture."+index,"test.world.title","test.world.desc","test.world.location","","test.world.next",WorldStateChangeKind.LocationUnlocked,WorldStateScopeKind.Shared,new[]{WorldStateBadgeKind.New,WorldStateBadgeKind.Shared},index,false);
[Test]public void WorldLogOffersReadableWideCardsAndScrollsLongHistory(){var p=Child("WorldPanel").AddComponent<WorldStateLogPanel>();p.Show(Enumerable.Range(0,8).Select(Model).ToArray());var root=(RectTransform)p.transform.Find("WorldStateLogRoot");Assert.That(root.rect.width,Is.GreaterThanOrEqualTo(1000));Assert.That(root.rect.height,Is.GreaterThanOrEqualTo(700));var scroll=p.GetComponentInChildren<ScrollRect>(true);Assert.That(scroll,Is.Not.Null,"Long world history needs bounded scrolling");Assert.That(scroll.content.rect.height,Is.GreaterThan(scroll.viewport.rect.height));var card=p.GetComponentsInChildren<WorldStateChangeCard>(true)[0];var r=(RectTransform)card.transform;Assert.That(r.anchorMin.y,Is.EqualTo(1));Assert.That(r.pivot.y,Is.EqualTo(1));Assert.That(card.transform.Find("Title").GetComponent<Text>().fontSize,Is.GreaterThanOrEqualTo(24));Assert.That(card.transform.Find("Body").GetComponent<Text>().fontSize,Is.GreaterThanOrEqualTo(18));Assert.That(((RectTransform)card.transform.Find("Title")).rect.width,Is.LessThanOrEqualTo(r.rect.width-64));var badge=(RectTransform)card.transform.Find("Badges");Assert.That(badge.anchoredPosition.y-badge.rect.height*.5f,Is.GreaterThanOrEqualTo(-r.rect.height*.5f+32f),"Badge glyphs must clear the approved molding at the bottom of the card");var footer=(RectTransform)root.Find("ScrollHint");Assert.That(footer.anchoredPosition.y-footer.rect.height*.5f,Is.GreaterThanOrEqualTo(-root.rect.height*.5f+32f),"Footer text must clear the outer molding");Assert.That(p.CardCountForTests,Is.EqualTo(8));}
[Test]public void EncyclopediaReservesFramePaddingAndReadableTextWithoutEmptyScrollTail(){var p=Child("Encyclopedia").AddComponent<EncyclopediaPanel>();((RectTransform)p.transform).sizeDelta=new Vector2(820,560);p.Show();var root=(RectTransform)p.transform;Assert.That(root.rect.width,Is.GreaterThanOrEqualTo(1200));Assert.That(root.rect.height,Is.GreaterThanOrEqualTo(760));Assert.That(p.transform.Find("EncyclopediaTitle").GetComponent<Text>().fontSize,Is.GreaterThanOrEqualTo(28));var body=p.transform.Find("EntryDetail/DetailBody").GetComponent<Text>();Assert.That(body.fontSize,Is.GreaterThanOrEqualTo(18));Assert.That(((RectTransform)body.transform).anchoredPosition.x,Is.GreaterThanOrEqualTo(28));var scroll=p.GetComponentInChildren<ScrollRect>(true);Assert.That(scroll,Is.Not.Null);Assert.That(scroll.viewport.rect.width,Is.LessThanOrEqualTo(((RectTransform)scroll.viewport.parent).rect.width-48));Assert.That(scroll.content.rect.height,Is.EqualTo(scroll.viewport.rect.height).Within(1),"Empty catalogue should not scroll through blank pooled rows");}
[TestCase("ko")][TestCase("en")]public void WorldCardResolvesFullAuthoredKeysAndLocalizedBadges(string lang){GameText.Language=lang;var p=Child("WorldPanel").AddComponent<WorldStateLogPanel>();p.Show(new[]{Model()});var card=p.GetComponentInChildren<WorldStateChangeCard>(true);Assert.That(card.TitleTextForTests,Is.EqualTo(catalog.Get("test.world.title",lang)));StringAssert.Contains(catalog.Get("test.world.desc",lang),card.BodyTextForTests);StringAssert.Contains(catalog.Get("test.world.location",lang),card.BodyTextForTests);StringAssert.Contains(catalog.Get("test.world.next",lang),card.BodyTextForTests);StringAssert.Contains(catalog.Get("day-result.world-badge.New",lang),card.BadgeTextForTests);StringAssert.Contains(catalog.Get("day-result.world-scope.Shared",lang),card.BadgeTextForTests);Assert.That(card.TitleTextForTests,Is.Not.EqualTo("title"));}
[TestCase("ko")][TestCase("en")]public void EncyclopediaResolvesCategoryRowsAndDetailFromAuthoredData(string lang){GameText.Language=lang;var category=ScriptableObject.CreateInstance<EncyclopediaCategoryDefinition>();definitions.Add(category);category.ConfigureForTests("category.fixture","test.ency.category",0);var entry=ScriptableObject.CreateInstance<EncyclopediaEntryDefinition>();definitions.Add(entry);entry.ConfigureForTests("entry.fixture",category,"test.ency.title","???","test.ency.description","test.ency.hint",new[]{"test.ency.detail"},Array.Empty<EncyclopediaUnlockConditionBase>());var progress=new EncyclopediaProgress("utility-locale-slot","actor");progress.TryUnlock(entry.Id,1,1L);var p=Child("Encyclopedia").AddComponent<EncyclopediaPanel>();p.Bind(new EncyclopediaIndex(new[]{category},new[]{entry}),progress);p.Show();var texts=p.GetComponentsInChildren<Text>(true).Select(t=>t.text).ToArray();Assert.That(texts,Does.Contain(catalog.Get("test.ency.category",lang)));Assert.That(texts,Does.Contain(catalog.Get("test.ency.title",lang)));StringAssert.Contains(catalog.Get("test.ency.description",lang),p.transform.Find("EntryDetail/DetailBody").GetComponent<Text>().text);StringAssert.Contains(catalog.Get("test.ency.detail",lang),p.transform.Find("EntryDetail/DetailBody").GetComponent<Text>().text);}
[TestCase("ko")][TestCase("en")]public void WorldMarkerAlsoResolvesTheFullKeyAndUsesTheSharedFontMaterial(string lang){GameText.Language=lang;var scene=UnityEditor.SceneManagement.EditorSceneManager.NewPreviewScene();var flag=ScriptableObject.CreateInstance<WorldStateFlagDefinition>();try{flag.ConfigureForTests("world.marker.fixture","test.world.title","test.world.desc",null,null,null,WorldStateScopeKind.Shared,WorldStateChangeKind.LocationUnlocked,"test.world.next",null,null,0,1);typeof(WorldStateSceneMarkerInstaller).GetMethod("EnsureMarker",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{scene,flag});var label=scene.GetRootGameObjects().SelectMany(x=>x.GetComponentsInChildren<TextMesh>()).Single();Assert.That(label.text,Is.EqualTo(catalog.Get("test.world.title",lang)));var font=(Font)typeof(WorldStateLogPanel).Assembly.GetType("Rootborn.UI.StudentLife.LifeUiFont").GetProperty("Shared").GetValue(null);Assert.That(label.font,Is.SameAs(font));Assert.That(label.GetComponent<Renderer>().sharedMaterial,Is.SameAs(font.material));}finally{UnityEditor.SceneManagement.EditorSceneManager.ClosePreviewScene(scene);UnityEngine.Object.DestroyImmediate(flag);}}[TestCase("ko")][TestCase("en")]public void EmptyCategoryClearsThePreviousEntryAndShowsUsefulGuidance(string lang){GameText.Language=lang;var filled=ScriptableObject.CreateInstance<EncyclopediaCategoryDefinition>();var empty=ScriptableObject.CreateInstance<EncyclopediaCategoryDefinition>();definitions.Add(filled);definitions.Add(empty);filled.ConfigureForTests("category.filled","test.ency.category",0);empty.ConfigureForTests("category.empty","Empty",1);var entry=ScriptableObject.CreateInstance<EncyclopediaEntryDefinition>();definitions.Add(entry);entry.ConfigureForTests("entry.fixture",filled,"test.ency.title","???","test.ency.description","test.ency.hint",new[]{"test.ency.detail"},Array.Empty<EncyclopediaUnlockConditionBase>());var progress=new EncyclopediaProgress("utility-empty-category","actor");progress.TryUnlock(entry.Id,1,1L);var p=Child("Encyclopedia").AddComponent<EncyclopediaPanel>();p.Bind(new EncyclopediaIndex(new[]{filled,empty},new[]{entry}),progress);p.Show();p.GetComponentsInChildren<Button>().Single(b=>b.name=="Category_category.empty").onClick.Invoke();var body=p.transform.Find("EntryDetail/DetailBody").GetComponent<Text>().text;Assert.That(body,Does.Not.Contain(catalog.Get("test.ency.description",lang)),"Empty categories must not keep the previous category's detail");Assert.That(body,Is.Not.Empty);Assert.That(p.GetComponentsInChildren<Button>().Any(b=>b.name.StartsWith("Entry_")),Is.False);var scroll=p.GetComponentInChildren<ScrollRect>();Assert.That(scroll.content.rect.height,Is.EqualTo(scroll.viewport.rect.height).Within(1));}}}
